+func TestDetectKBsFromKernelVersionRecentRollups(t *testing.T) {
+	tests := []struct {
+		name, release, build string
+		firstRevision        int
+		newKBs               []string
+	}{
+		{"Windows 10 22H2", "Windows 10 Version 22H2 for x64-based Systems", "19045", 3693, []string{"5032189", "5032278", "5033372", "5034122", "5034203", "5034763", "5034843", "5035845", "5035941", "5036892", "5036979", "5037768", "5037849", "5039211"}},
+		{"Windows 11 22H2", "Windows 11 Version 22H2 for x64-based Systems", "22621", 2715, []string{"5032190", "5032288", "5033375", "5034123", "5034204", "5034765", "5034848", "5035853", "5035942", "5036893", "5036980", "5037771", "5037853", "5039212"}},
