+func TestDetectKBsFromKernelVersionRecentRollups(t *testing.T) {
+	tests := []struct {
+		name, release, build string
+		firstRevision        int
+		newKBs               []string
+	}{
+		{"Windows 10 22H2", "Windows 10 Version 22H2 for x64-based Systems", "19045", 3693, []string{"5032189", "5032278", "5033372", "5034122", "5034203", "5034763", "5034843", "5035845", "5035941", "5036892", "5036979", "5037768", "5037849", "5039211"}},
+		{"Windows 11 22H2", "Windows 11 Version 22H2 for x64-based Systems", "22621", 2715, []string{"5032190", "5032288", "5033375", "5034123", "5034204", "5034765", "5034848", "5035853", "5035942", "5036893", "5036980", "5037771", "5037853", "5039212"}},
+		{"Windows 11 23H2", "Windows 11 Version 23H2 for x64-based Systems", "22631", 2715, []string{"5032190", "5032288", "5033375", "5034123", "5034204", "5034765", "5034848", "5035853", "5035942", "5036893", "5036980", "5037771", "5037853", "5039212"}},
+		{"Windows Server 2022", "Windows Server 2022", "20348", 2113, []string{"5032198", "5033118", "5034129", "5034770", "5035857", "5037422", "5036909", "5037782", "5039227"}},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			prefix := "10.0." + tt.build + "."
+			before, err := DetectKBsFromKernelVersion(tt.release, prefix+strconv.Itoa(tt.firstRevision-1))
+			if err != nil {
+				t.Fatal(err)
+			}
+			if !reflect.DeepEqual(before.Unapplied[len(before.Unapplied)-len(tt.newKBs):], tt.newKBs) {
+				t.Errorf("new KBs before first revision: got %v, want %v", before.Unapplied, tt.newKBs)
+			}
+			at, err := DetectKBsFromKernelVersion(tt.release, prefix+strconv.Itoa(tt.firstRevision))
+			if err != nil {
+				t.Fatal(err)
+			}
+			if !slices.Contains(at.Applied, tt.newKBs[0]) || slices.Contains(at.Unapplied, tt.newKBs[0]) {
+				t.Errorf("first KB at its revision: %+v", at)
+			}
+			high, err := DetectKBsFromKernelVersion(tt.release, prefix+"9999")
+			if err != nil {
+				t.Fatal(err)
+			}
+			if len(high.Unapplied) != 0 || !reflect.DeepEqual(high.Applied[len(high.Applied)-len(tt.newKBs):], tt.newKBs) {
+				t.Errorf("new KBs at high revision: got %+v, want applied tail %v", high, tt.newKBs)
+			}
+		})
+	}
